Cyclotomic<N>::root_of_unity_order.body:
{
        if N == 0 || N > omega_number_theory::polynomial::MAX_CONDUCTOR {
            return 0;
        }
        let order = if N % 2 == 0 { N } else { 2 * N };
        u32::try_from(order).unwrap_or(u32::MAX)
    }

Cyclotomic<N>::primitive_root_of_unity.body:
{
        if N % 2 == 0 {
            Cyclotomic::zeta(1)
        } else {
            let exponent = i64::try_from((N + 1) / 2).unwrap_or(1);
            Cyclotomic::zeta(exponent).neg()
        }
    }
